//! RFC 8785 JCS 权威向量(Phase 3,SPEC §10.2)。
//!
//! 事件签名、event_id、Merkle 叶都依赖 JCS(event body 的规范化 JSON)。
//! 权威实现 = 本模块(serde_jcs 生成期望字节);Python 侧 `music_zk/protocol/jcs.py`
//! 必须逐字节一致——tests/test_jcs.py 从本文件抄向量(与 framing 对拍同一模式)。
//!
//! 样本覆盖:三类事件 body(SPEC §11.1)+ RFC 8785 对抗用例(键排序/unicode/转义/
//! 数字格式化/嵌套/空值)。浮点数按 RFC 8785 ES6 Number 序列化(-0.0→"0"、1e3→"1000")。

use serde_json::json;

const PK: &str = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
const PROTOCOL: &str = "music-zk-exhibit/midi-profile-1/reference-synth-1/statement-2";

fn assert_jcs(name: &str, value: serde_json::Value, expect_hex: &str) {
    let got = serde_jcs::to_string(&value).expect("serde_jcs 序列化失败");
    let expect = hex::decode(expect_hex).expect("期望 hex 非法");
    assert_eq!(
        got.as_bytes(),
        expect.as_slice(),
        "JCS 向量不符: {name}\n got: {got}"
    );
}

#[test]
fn jcs_vectors_rfc8785() {
    assert_jcs(
        "commit_event",
        json!({
            "client_nonce": "a1b2c3d4e5f60718293a4b5c6d7e8f90",
            "creator_pubkey": PK,
            "event_type": "COMMIT",
            "protocol_id": PROTOCOL,
            "commit": {"c_m": "0717cc993bef93ce97480167625612992f230690779944c9ab69f650cbb97c68"},
        }),
        "",
    );
    assert_jcs(
        "release_event",
        json!({
            "client_nonce": "00000000000000000000000000000000",
            "creator_pubkey": PK,
            "event_type": "RELEASE",
            "protocol_id": PROTOCOL,
            "commit_event_id": "5c0d4d0e8f2c9f2f0c1a2b3c4d5e6f70819a2b3c4d5e6f70819a2b3c4d5e6f7081",
            "release": {
                "c_s": "8c2d4e6f8a0b1c2d3e4f5a6b7c8d9e0f1a2b3c4d5e6f708192a3b4c5d6e7f8091",
                "song_file": {"name": "my-song.flac", "size": 1234567, "mime": "audio/flac"},
            },
        }),
        "",
    );
    assert_jcs(
        "proof_event",
        json!({
            "client_nonce": "ffffffffffffffffffffffffffffffff",
            "creator_pubkey": PK,
            "event_type": "PROOF",
            "protocol_id": PROTOCOL,
            "commit_event_id": "5c0d4d0e8f2c9f2f0c1a2b3c4d5e6f70819a2b3c4d5e6f70819a2b3c4d5e6f7081",
            "release_event_id": "9f8e7d6c5b4a39281726354a5b6c7d8e9f0a1b2c3d4e5f60718293a4b5c6d7e8f90",
            "proof": {
                "c_v": "2498454557a1603b8d5b47ebd4f135103c62266534e829a9d5370f1f7ae4c4f9",
                "journal_hash": "aaaa0000111122223333444455556666777788889999aaaabbbbccccddddeeeeffff",
                "receipt_hash": PK,
                "v_hash": "102030405060708090a0b0c0d0e0f0a1b2c3d4e5f60718293a4b5c6d7e8f90a1b",
                "manifest_hash": "deadbeefcafebabe1234567890abcdef1234567890abcdef1234567890abcdef",
            },
        }),
        "",
    );
    assert_jcs(
        "key_order_scrambled",
        json!({
            "z": 1, "a": 2, "m": 3, "b": {"y": 1, "x": 2}, "arr": [{"k2": 2, "k1": 1}],
        }),
        "7b2261223a322c22617272223a5b7b226b31223a312c226b32223a327d5d2c2262223a7b2278223a322c2279223a317d2c226d223a332c227a223a317d",
    );
    assert_jcs(
        "unicode",
        json!({"s": "café ☕ 中文"}),
        "7b2273223a22636166c3a920e2989520e4b8ade69687227d",
    );
    assert_jcs(
        "escaped_controls",
        json!({"t": "tab\there", "n": "newline\n", "q": "quo\"te", "b": "back\\slash", "c": "ctrl\u{1}"}),
        "7b2262223a226261636b5c5c736c617368222c2263223a226374726c5c7530303031222c226e223a226e65776c696e655c6e222c2271223a2271756f5c227465222c2274223a227461625c7468657265227d",
    );
    assert_jcs(
        "numbers",
        json!({"i": 42, "neg": -17, "big": 9007199254740991i64, "float": 1.5, "zero": 0,
               "negzero": -0.0, "exp": 1000.0, "small": 0.1, "expneg": 0.00000015}),
        "7b22626967223a393030373139393235343734303939312c22657870223a313030302c226578706e6567223a312e35652d372c22666c6f6174223a312e352c2269223a34322c226e6567223a2d31372c226e65677a65726f223a302c22736d616c6c223a302e312c227a65726f223a307d",
    );
    assert_jcs(
        "nested",
        json!({"a": [{"b": [1, 2, {"c": null}]}], "e": {}}),
        "7b2261223a5b7b2262223a5b312c322c7b2263223a6e756c6c7d5d7d5d2c2265223a7b7d7d",
    );
    assert_jcs("empty", json!({}), "7b7d");
    assert_jcs("array_empty", json!([]), "5b5d");
    assert_jcs("null_bool", json!([null, true, false]), "5b6e756c6c2c747275652c66616c73655d");
    assert_jcs(
        "deep",
        json!({"l1": {"l2": {"l3": {"l4": [0, "s", {"k": "v"}]}}}}),
        "7b226c31223a7b226c32223a7b226c33223a7b226c34223a5b302c2273222c7b226b223a2276227d5d7d7d7d7d",
    );
}
